// Normaliza el identificador: email, teléfono o cédula.
// Sólo se busca por teléfono/cédula cuando hay al menos 6 dígitos, para evitar
// coincidencias accidentales con valores muy cortos.
const body = $input.first().json.body || $input.first().json || {};
const raw = String(body.identifier || '').trim();

if (!raw) {
  return [{ json: { __error: true, statusCode: 400, message: 'identifier is required' } }];
}

const digits = raw.replace(/\D/g, '');

return [{ json: {
  identifier: raw,
  email_candidate: raw.toLowerCase(),
  digits_candidate: digits.length >= 6 ? digits : '__no_match__',
  supplied_email: String(body.email || '').trim().toLowerCase(),
} }];

function maskEmail(email) {
  if (!email) return null;
  const [user, domain] = String(email).split('@');
  if (!domain) return null;
  const head = user.slice(0, 1);
  const tail = user.length > 1 ? user.slice(-1) : '';
  return `${head}***${tail}@${domain}`;
}

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const user = rows[0];

if (!user) {
  return [{ json: { statusCode: 200, body: {
    found: false, needs_email: false, masked_email: null,
  } } }];
}

const hasEmail = !!(user.email && String(user.email).trim());

// `user_id` y `name` son el mínimo para poder reservar sin sesión.
// NO agregar email, teléfono ni ningún otro dato: este endpoint es público.
return [{ json: { statusCode: 200, body: {
  found: true,
  needs_email: !hasEmail,
  masked_email: hasEmail ? maskEmail(user.email) : null,
  user_id: user.id,
  name: user.name || null,
  has_upcoming_appointments: user.has_upcoming_appointments === true,
} } }];

// Normaliza el identificador: email, teléfono o cédula.
// Sólo se busca por teléfono/cédula cuando hay al menos 6 dígitos, para evitar
// coincidencias accidentales con valores muy cortos.
const body = $input.first().json.body || $input.first().json || {};
const raw = String(body.identifier || '').trim();

if (!raw) {
  return [{ json: { __error: true, statusCode: 400, message: 'identifier is required' } }];
}

const digits = raw.replace(/\D/g, '');

return [{ json: {
  identifier: raw,
  email_candidate: raw.toLowerCase(),
  digits_candidate: digits.length >= 6 ? digits : '__no_match__',
  supplied_email: String(body.email || '').trim().toLowerCase(),
} }];

function maskEmail(email) {
  if (!email) return null;
  const [user, domain] = String(email).split('@');
  if (!domain) return null;
  const head = user.slice(0, 1);
  const tail = user.length > 1 ? user.slice(-1) : '';
  return `${head}***${tail}@${domain}`;
}

// Genera el código de 6 dígitos y valida el rate-limit de reenvío (60 s).
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const user = rows[0];
const ctx  = $('Normalizar Identificador1').first().json;

if (!user) {
  return [{ json: { __respond: true, statusCode: 404, body: { message: 'No encontramos ese paciente.' } } }];
}

if (user.login_code_sent_at) {
  const elapsed = (Date.now() - new Date(user.login_code_sent_at).getTime()) / 1000;
  if (elapsed < 60) {
    return [{ json: { __respond: true, statusCode: 429, body: {
      message: 'Esperá unos segundos antes de pedir otro código.',
      retry_after: Math.ceil(60 - elapsed),
    } } }];
  }
}

// El email a usar: el que ya tiene, o el que acaba de ingresar el paciente.
const targetEmail = String(user.email || '').trim() || ctx.supplied_email;
if (!targetEmail) {
  return [{ json: { __respond: true, statusCode: 400, body: { message: 'Necesitamos un correo para enviarte el código.' } } }];
}

// Código de 6 dígitos, evitando los que tienen todos los dígitos iguales.
let code;
do {
  code = String(Math.floor(100000 + Math.random() * 900000));
} while (/^(\d)\1{5}$/.test(code));

return [{ json: {
  user_id: user.id,
  user_name: user.name,
  target_email: targetEmail,
  // Sólo se persiste cuando el usuario no tenía email cargado.
  email_to_persist: String(user.email || '').trim() ? null : targetEmail,
  code,
  masked_email: maskEmail(targetEmail),
} }];

const item = $input.first().json;
const ctx  = $('Generar Código1').first().json;

if (item && item.error) {
  return [{ json: { statusCode: 500, body: { message: 'No pudimos generar el código. Intentá de nuevo.' } } }];
}

return [{ json: { statusCode: 200, body: {
  sent: true,
  masked_email: ctx.masked_email,
  expires_in: 600,
} } }];

// Arma el payload público. NUNCA agregar campos sensibles: este endpoint es
// accesible sin token por cualquiera que abra /patient-login.
const rows = $input.all().map(i => i.json).filter(r => r && r.name);
const clinic = rows[0];

if (!clinic) {
  return [{ json: { statusCode: 404, body: { message: 'No hay una clínica configurada.' } } }];
}

// El logo se adjunta como data URI por el nodo siguiente si existe el binario.
return [{ json: { statusCode: 200, body: {
  name: clinic.name,
  address: clinic.address || null,
  phone: clinic.phone || null,
  email: clinic.email || null,
  logo_url: null,
  welcome_video_url: clinic.welcome_video_url || null,
  welcome_message: clinic.welcome_message || null,
  patient_portal_enabled: clinic.patient_portal_enabled === true,
  // Modos del portal — deciden el flujo de /patient-login (ver §3).
  online_booking_enabled: clinic.online_booking_enabled !== false,
  appointments_only: clinic.appointments_only === true,
  // Selección de servicios. `show_pricing` es sólo presentación: la duración
  // del servicio dimensiona el hueco de la agenda esté visible o no.
  service_selection_enabled: clinic.service_selection_enabled === true,
  show_pricing: clinic.show_pricing === true,
  default_service: clinic.default_service || null,
  schedules: clinic.schedules || [],
} } }];

// El patient_id efectivo SIEMPRE sale del JWT, nunca del body: un paciente no
// puede consultar por otro.
const headers = $input.first().json.headers || {};
const authHeader = (headers.authorization || headers.Authorization || '');
const token = authHeader.replace(/^Bearer\s+/i, '').trim();

if (!token) throw new Error('UNAUTHORIZED: falta el token');

const payloadPart = token.split('.')[1];
if (!payloadPart) throw new Error('UNAUTHORIZED: token mal formado');

const decoded = JSON.parse(
  Buffer.from(payloadPart.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8')
);

const body = $input.first().json.body || {};

return [{ json: {
  patient_id: decoded.sub,          // ← autoritativo
  query: String(body.query || '').trim(),
  channel: body.channel || 'text',
  session_id: body.session_id || null,
  has_existing_session: !!body.has_existing_session,
} }];

// Normaliza la salida del agente al contrato PatientAiQueryResponse.
const raw = $input.first().json;
const text = raw.output || raw.text || raw.answer || '';

let action = { type: 'none', payload: null };
const match = String(text).match(/\{\s*"action"[\s\S]*\}/);
if (match) {
  try { action = JSON.parse(match[0]).action || action; } catch (e) { /* texto plano */ }
}

return [{ json: { statusCode: 200, body: {
  answer: String(text).replace(/\{\s*"action"[\s\S]*\}/, '').trim(),
  speak_text: String(text).replace(/\{\s*"action"[\s\S]*\}/, '').trim(),
  suggestions: raw.suggestions || [],
  action,
} } }];

// Claims EXACTAMENTE como los emite /api/auth/login. Verificado decodificando un
// token real del sistema:
//   { "userId": "<uuid>", "email": "...", "expiresIn": "24h", "iat": <epoch> }
//
// Ojo con lo que NO lleva:
//   · No hay `sub`  → el identificador del usuario va en `userId`.
//   · No hay `roles`→ /auth/me los resuelve consultando user_roles en la BD.
//   · No hay `exp`  → "expiresIn" es un claim literal, no la opción de jsonwebtoken.
// `iat` lo agrega solo el nodo JWT al firmar.
const ctx = $('Validar Código').first().json;

return [{ json: {
  userId: ctx.user_id,
  email: ctx.email,
  expiresIn: '24h',
} }];

// Normaliza el identificador: email, teléfono o cédula.
// Sólo se busca por teléfono/cédula cuando hay al menos 6 dígitos, para evitar
// coincidencias accidentales con valores muy cortos.
const body = $input.first().json.body || $input.first().json || {};
const raw = String(body.identifier || '').trim();

if (!raw) {
  return [{ json: { __error: true, statusCode: 400, message: 'identifier is required' } }];
}

const digits = raw.replace(/\D/g, '');

return [{ json: {
  identifier: raw,
  email_candidate: raw.toLowerCase(),
  digits_candidate: digits.length >= 6 ? digits : '__no_match__',
  supplied_email: String(body.email || '').trim().toLowerCase(),
} }];

// El nodo JWT devuelve { token }. El usuario sale del paso de validación —
// deliberadamente NO se devuelve users.password ni ningún otro campo interno.
const ctx = $('Validar Código').first().json;
const token = $input.first().json.token;

if (!token) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo emitir el token de acceso.' } } }];
}

return [{ json: { statusCode: 200, body: {
  token,
  user: { id: ctx.user_id, name: ctx.name, email: ctx.email },
  is_new: ctx.is_new === true,
} } }];

// Valida el código contra el hash guardado, la expiración y los intentos.
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const user = rows[0];
const body = $('POST api/auth/patient/verify-code').first().json.body || {};
const code = String(body.code || '').trim();

if (!user) {
  return [{ json: { __respond: true, statusCode: 404, body: { message: 'No encontramos ese paciente.' } } }];
}
if (!user.login_code || !user.login_code_expires_at) {
  return [{ json: { __respond: true, statusCode: 410, body: { message: 'Pedí un código nuevo.' } } }];
}
if (new Date(user.login_code_expires_at).getTime() < Date.now()) {
  return [{ json: { __respond: true, statusCode: 410, body: { message: 'El código venció. Pedí uno nuevo.' } } }];
}
if (Number(user.login_code_attempts || 0) >= 5) {
  return [{ json: { __respond: true, statusCode: 429, body: { message: 'Demasiados intentos. Pedí un código nuevo.' } } }];
}

const crypto = require('crypto');
const hash = crypto.createHash('sha256').update(code + String(user.id)).digest('hex');

if (hash !== user.login_code) {
  return [{ json: { __respond: false, __invalid: true, user_id: user.id,
                    statusCode: 401, body: { message: 'El código no es correcto.' } } }];
}

// is_new: registrado hace menos de 30 min y sin haber entrado nunca al portal.
const createdAt = user.created_at ? new Date(user.created_at).getTime() : 0;
const isNew = !user.is_portal_user && createdAt > Date.now() - 30 * 60 * 1000;

return [{ json: {
  __respond: false, __invalid: false,
  user_id: user.id, name: user.name, email: user.email, is_new: isNew,
} }];

// Sólo se aceptan estos cinco campos. Nada de nombre, RUT ni datos fiscales:
// esos se editan en Datos de la Clínica, no acá.
const body = $input.first().json.body ?? $input.first().json ?? {};

const asBool = (v) => v === true || v === 'true';
const asText = (v) => {
  const s = v == null ? '' : String(v).trim();
  return s === '' ? null : s;
};

return [{ json: {
  patient_portal_enabled:           asBool(body.patient_portal_enabled),
  patient_portal_online_booking:    asBool(body.online_booking_enabled),
  patient_portal_appointments_only: asBool(body.appointments_only),
  welcome_video_url:                asText(body.welcome_video_url),
  welcome_message:                  asText(body.welcome_message),
} }];

const row = $input.first().json;

if (!row || row.error || !row.id) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo guardar la configuración del portal.' } } }];
}

return [{ json: { statusCode: 200, body: {
  success: true,
  patient_portal_enabled: row.patient_portal_enabled === true,
  online_booking_enabled: row.patient_portal_online_booking === true,
  appointments_only:      row.patient_portal_appointments_only === true,
  welcome_video_url:      row.welcome_video_url,
  welcome_message:        row.welcome_message,
} } }];

// Datos del cambio + destinatarios. La clínica se saca de la BD para no
// confiar en nada que venga del cliente.
const body = $input.first().json.body ?? $input.first().json ?? {};

// El email puede llegar vacío y NO es un error: `/api/auth/patient/identify`
// es público y sólo devuelve el email enmascarado, así que el cliente no
// conoce la dirección real de un paciente ya registrado. Se resuelve contra la
// BD por patient_id en el nodo siguiente.
const patientEmail = String(body.patient_email || '').trim();
const patientId = body.patient_id || null;
if (!patientEmail && !patientId) {
  throw new Error('Se requiere patient_email o patient_id');
}

const VALID_EVENTS = ['booked', 'rescheduled', 'cancelled'];
const event = VALID_EVENTS.includes(body.event) ? body.event : 'booked';

// Copy por evento. Se arma acá y no en los nodos de email para que el asunto y
// el encabezado no queden desperdigados en expresiones.
const COPY = {
  booked: {
    patientSubject: 'Tu cita quedó agendada',
    patientHeadline: 'Tu cita quedó agendada.',
    clinicSubject:  'Nueva cita desde el portal',
    clinicHeadline: 'Un paciente reservó una cita desde el portal.',
  },
  rescheduled: {
    patientSubject: 'Tu cita fue reagendada',
    patientHeadline: 'Reagendamos tu cita. Este es el nuevo horario.',
    clinicSubject:  'Cita reagendada desde el portal',
    clinicHeadline: 'Un paciente reagendó su cita desde el portal.',
  },
  cancelled: {
    patientSubject: 'Tu cita fue cancelada',
    patientHeadline: 'Cancelamos tu cita. El horario quedó liberado.',
    clinicSubject:  'Cita cancelada desde el portal',
    clinicHeadline: 'Un paciente canceló su cita desde el portal.',
  },
}[event];

const previous = body.previous_date
  ? `${body.previous_date} ${String(body.previous_time || '').trim()}`.trim()
  : '';

return [{ json: {
  event,
  ...COPY,
  previous,
  is_cancelled:  event === 'cancelled',
  appointment_id: body.appointment_id || null,
  patient_id:     patientId,
  patient_name:   String(body.patient_name || '').trim(),
  patient_email:  patientEmail,
  date:           String(body.date || '').trim(),
  time:           String(body.time || '').trim(),
  doctor_name:    String(body.doctor_name || '').trim(),
  sede_name:      String(body.sede_name || '').trim(),
  reason:         String(body.reason || '').trim(),
} }];

const row = $input.first().json || {};
const ctx = $('Preparar Datos').first().json;

// La BD manda: es la dirección que la clínica tiene registrada. El valor del
// body sólo se usa como respaldo (paciente recién creado, cuya fila todavía
// podría no estar visible para esta consulta).
const patientEmail = String(row.db_patient_email || ctx.patient_email || '').trim();

if (!patientEmail) {
  throw new Error(`No hay email para notificar al paciente ${ctx.patient_id ?? '(sin id)'}`);
}

return [{ json: {
  ...ctx,
  patient_email: patientEmail,
  patient_name:  ctx.patient_name || row.db_patient_name || '',
  clinic_name:   row.clinic_name  || 'la clínica',
  clinic_email:  row.clinic_email || null,
  clinic_phone:  row.clinic_phone || '',
} }];

// Normaliza el webhook de rebote del proveedor SMTP. El nombre del campo varía
// entre proveedores; se prueban los más comunes.
const body = $input.first().json.body ?? $input.first().json ?? {};

const email = String(
  body.email || body.recipient || body.to ||
  body['email-address'] || body?.envelope?.to || ''
).trim().toLowerCase();

if (!email) throw new Error('No se pudo determinar el email que rebotó');

return [{ json: { email } }];

// Valida el payload mínimo de auto-registro: nombre, teléfono y email.
const body = $input.first().json.body || $input.first().json || {};

const name  = String(body.name || '').trim();
const phone = String(body.phone || '').trim();
const email = String(body.email || '').trim().toLowerCase();

// El teléfono es opcional: sirve para que la clínica pueda contactarlo, pero
// no bloquea el registro. El email sí es obligatorio: es la credencial del
// paciente y a donde llega el código de acceso.
if (!name || !email) {
  return [{ json: { __respond: true, statusCode: 400,
                    body: { message: 'Nombre y email son obligatorios.' } } }];
}

// Nombre de paciente: misma regla que src/lib/person-name.ts (frontend). Letras de
// cualquier alfabeto separadas por un espacio, guion, apóstrofo o punto de
// abreviatura; sin números ni otros símbolos. No exige apellido ni toca mayúsculas.
const normalizeName = (v) => String(v ?? '').trim().replace(/\s+/g, ' ');
const NAME_RE = /^[\p{L}\p{M}]+(?:(?:\. ?|[ '’-])[\p{L}\p{M}]+)*\.?$/u;
const isValidName = (v) => {
  const n = normalizeName(v);
  return n.length > 0 && n.length <= 120 && NAME_RE.test(n) && (n.match(/\p{L}/gu) || []).length >= 2;
};
if (!isValidName(name)) {
  return [{ json: { __respond: true, statusCode: 400, body: {
    error: { code: 'invalid_name', conflictedFields: ['name'] },
    message: 'El nombre solo puede tener letras, espacios, guiones, apóstrofos y puntos.',
  } } }];
}

return [{ json: {
  name: normalizeName(name), email,
  phone: phone || null,
  identity_document: String(body.identity_document || '').replace(/\D/g, '') || null,
  birth_date: String(body.birth_date || '').trim() || null,
  address: String(body.address || '').trim() || null,
  // '__no_match__' evita que un teléfono vacío colisione con filas sin teléfono.
  phone_digits: phone ? phone.replace(/\D/g, '') : '__no_match__',
  // Modo "sólo citas": el paciente no verifica nada, mandarle un código
  // sería un correo inútil. Lo pide el frontend con skip_code.
  skip_code: body.skip_code === true || body.skip_code === 'true',
} }];

// El frontend ya sabe leer este formato de conflicto (ver patient-form-utils.ts).
// Si la validación ya armó una respuesta (400), se devuelve sin evaluar nada.
const validated = $('Validar Datos').first().json;
if (validated.__respond) return [{ json: validated }];

const row = $input.first().json || {};
const conflicted = [];
if (row.email_taken)    conflicted.push('email');
if (row.phone_taken)    conflicted.push('phone');
if (row.document_taken) conflicted.push('identity_document');

if (conflicted.length) {
  return [{ json: { __respond: true, statusCode: 409, body: {
    error: { code: 'unique_conflict', conflictedFields: conflicted },
    message: 'Ya existe una cuenta con esos datos.',
  } } }];
}

return [{ json: { ...$('Validar Datos').first().json, __respond: false } }];

function maskEmail(email) {
  if (!email) return null;
  const [user, domain] = String(email).split('@');
  if (!domain) return null;
  const head = user.slice(0, 1);
  const tail = user.length > 1 ? user.slice(-1) : '';
  return `${head}***${tail}@${domain}`;
}

// Genera y persiste el código para el usuario recién creado.
const created = $('Crear Usuario').first().json;
let code;
do {
  code = String(Math.floor(100000 + Math.random() * 900000));
} while (/^(\d)\1{5}$/.test(code));

return [{ json: {
  user_id: created.id,
  user_name: created.name,
  target_email: created.email,
  code,
  masked_email: maskEmail(created.email),
} }];

// Usuario creado, sin código: en modo "sólo citas" el paciente pasa directo a
// la agenda y nunca va a verificar su correo.
const created = $('Crear Usuario').first().json;
return [{ json: { statusCode: 200, body: {
  created: true,
  user_id: created.id,
  name: created.name,
  email: created.email,
  sent: false,
  masked_email: null,
} } }];

const ctx = $('Generar Código').first().json;
return [{ json: { statusCode: 200, body: {
  created: true,
  user_id: ctx.user_id,
  sent: true,
  masked_email: ctx.masked_email,
  expires_in: 600,
} } }];

// Arma el payload público. NUNCA agregar campos sensibles: este endpoint es
// accesible sin token por cualquiera que abra /patient-login.
const rows = $input.all().map(i => i.json).filter(r => r && r.name);
const clinic = rows[0];

if (!clinic) {
  return [{ json: { statusCode: 404, body: { message: 'No hay una clínica configurada.' } } }];
}

// El logo se adjunta como data URI por el nodo siguiente si existe el binario.
return [{ json: { statusCode: 200, body: {
  name: clinic.name,
  address: clinic.address || null,
  phone: clinic.phone || null,
  email: clinic.email || null,
  logo_url: null,
  welcome_video_url: clinic.welcome_video_url || null,
  welcome_message: clinic.welcome_message || null,
  patient_portal_enabled: clinic.patient_portal_enabled === true,
  // Modos del portal — deciden el flujo de /patient-login (ver §3).
  online_booking_enabled: clinic.online_booking_enabled !== false,
  appointments_only: clinic.appointments_only === true,
  schedules: clinic.schedules || [],
} } }];

// Sólo se aceptan estos diez campos. Nada de nombre, RUT ni datos fiscales:
// esos se editan en Datos de la Clínica, no acá.
const body = $input.first().json.body ?? $input.first().json ?? {};

const asBool = (v) => v === true || v === 'true';
const asText = (v) => {
  const s = v == null ? '' : String(v).trim();
  return s === '' ? null : s;
};
// El id del servicio por defecto es un entero; cualquier cosa que no lo sea
// (vacío, null, texto) se guarda como NULL ⇒ sin servicio por defecto.
const asServiceId = (v) => {
  const n = Number(v);
  return Number.isInteger(n) && n > 0 ? n : null;
};

// Ventana de reserva. Se acota acá para no chocar con el CHECK de la tabla:
// días de 1 a 365, meses de 1 a 12.
const windowUnit = body.booking_window_unit === 'months' ? 'months' : 'days';
const windowMax = windowUnit === 'months' ? 12 : 365;
const windowRaw = Math.trunc(Number(body.booking_window_value));
const windowValue = windowRaw >= 1 ? Math.min(windowRaw, windowMax) : Math.min(30, windowMax);

return [{ json: {
  patient_portal_enabled:           asBool(body.patient_portal_enabled),
  patient_portal_online_booking:    asBool(body.online_booking_enabled),
  patient_portal_appointments_only: asBool(body.appointments_only),
  patient_portal_service_selection: asBool(body.service_selection_enabled),
  patient_portal_show_pricing:      asBool(body.show_pricing),
  patient_portal_default_service_id: asServiceId(body.default_service_id),
  welcome_video_url:                asText(body.welcome_video_url),
  welcome_message:                  asText(body.welcome_message),
  patient_portal_booking_window_unit:  windowUnit,
  patient_portal_booking_window_value: windowValue,
} }];

const row = $input.first().json;

if (!row || row.error || !row.id) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo guardar la configuración del portal.' } } }];
}

return [{ json: { statusCode: 200, body: {
  success: true,
  patient_portal_enabled: row.patient_portal_enabled === true,
  online_booking_enabled: row.patient_portal_online_booking === true,
  appointments_only:      row.patient_portal_appointments_only === true,
  service_selection_enabled: row.patient_portal_service_selection === true,
  show_pricing:              row.patient_portal_show_pricing === true,
  default_service_id:        row.patient_portal_default_service_id,
  booking_window_unit:       row.patient_portal_booking_window_unit,
  booking_window_value:      row.patient_portal_booking_window_value,
  welcome_video_url:      row.welcome_video_url,
  welcome_message:        row.welcome_message,
} } }];

// Arma el payload público. NUNCA agregar campos sensibles: este endpoint es
// accesible sin token por cualquiera que abra /patient-login.
const rows = $input.all().map(i => i.json).filter(r => r && r.name);
const clinic = rows[0];

if (!clinic) {
  return [{ json: { statusCode: 404, body: { message: 'No hay una clínica configurada.' } } }];
}

// El logo se adjunta como data URI por el nodo siguiente si existe el binario.
return [{ json: { statusCode: 200, body: {
  name: clinic.name,
  address: clinic.address || null,
  phone: clinic.phone || null,
  email: clinic.email || null,
  logo_url: null,
  welcome_video_url: clinic.welcome_video_url || null,
  welcome_message: clinic.welcome_message || null,
  patient_portal_enabled: clinic.patient_portal_enabled === true,
  // Modos del portal — deciden el flujo de /patient-login (ver §3).
  online_booking_enabled: clinic.online_booking_enabled !== false,
  appointments_only: clinic.appointments_only === true,
  // Selección de servicios. `show_pricing` es sólo presentación: la duración
  // del servicio dimensiona el hueco de la agenda esté visible o no.
  service_selection_enabled: clinic.service_selection_enabled === true,
  show_pricing: clinic.show_pricing === true,
  default_service: clinic.default_service || null,
  // Hasta qué fecha puede reservar el paciente. El servidor lo vuelve a validar
  // al crear la cita: esto sólo decide qué días se ofrecen.
  booking_window_unit: clinic.booking_window_unit === 'months' ? 'months' : 'days',
  booking_window_value: Number(clinic.booking_window_value) || 30,
  schedules: clinic.schedules || [],
} } }];
